//! `cargo xtask docs`: builds the commentable HTML pages from the Markdown sources and the
//! check catalogue (ADR-0020, COMP-06). The Markdown and the catalogue are the single sources;
//! the generated pages are never edited by hand, and DOC-GENERATED fails when they are stale.

pub(crate) mod building_blocks;
mod markdown;
mod page;
pub(crate) mod source;
pub(crate) mod text;

use crate::catalog::Catalog;
use crate::generate::Generated;
use crate::repo::Repo;

/// Every generated file carries this text in its first lines, so people and META-COVERAGE can
/// tell it is not hand-written.
pub(crate) const GENERATED_MARKER: &str = "GENERATED by";

/// The paths of the files `cargo xtask docs` produces.
pub(crate) fn generated_paths() -> Vec<&'static str> {
    vec![page::ARCHITECTURE_PATH, page::MILESTONES_PATH]
}

/// Every file `cargo xtask docs` produces.
pub(crate) fn generate(repo: &Repo, catalog: &Catalog) -> anyhow::Result<Vec<Generated>> {
    Ok(vec![
        Generated::new(page::ARCHITECTURE_PATH, page::architecture(repo, catalog)?),
        Generated::new(page::MILESTONES_PATH, page::milestones(repo)?),
    ])
}
